from decimal import Decimal


def totals_by_customer(orders):
    """Sum non-cancelled order amounts per customer.

    Amounts are accumulated with :class:`~decimal.Decimal` for exact
    arithmetic. Orders whose ``status`` is ``"cancelled"`` are skipped; a
    missing ``status`` is treated as active. The returned mapping is ordered
    by customer ID.
    """
    totals = {}
    for order in orders:
        if order.get('status') == 'cancelled':
            continue
        customer_id = order['customer_id']
        amount = Decimal(str(order['amount']))
        totals[customer_id] = totals.get(customer_id, Decimal('0')) + amount
    return {customer_id: totals[customer_id] for customer_id in sorted(totals)}

